export type RequestInput={booking_code:string;chilled_crates:number;frozen_crates:number;loading_docks:number;rush_load:boolean};export const score=(a:number,b:number,d:number,r:boolean)=>{const t=a+b,x=a*7+b*15+(r?d*5:0),c=d*44;return Math.min(x,c)+Math.max(x-c,0)*5+Math.trunc(t/6)*8};export const calculate=(v:RequestInput)=>{const t=v.chilled_crates+v.frozen_crates,x=v.chilled_crates*7+v.frozen_crates*15+(v.rush_load?v.loading_docks*5:0),c=v.loading_docks*44,d=Math.max(x-c,0);return {booking_code:v.booking_code,shipment_total:t,cooling_units:x,dock_capacity_units:c,loaded_units:Math.min(x,c),deferred_units:d,loading_rounds:Math.trunc(t/6),booking_score:score(v.chilled_crates,v.frozen_crates,v.loading_docks,v.rush_load),booking_state:d===0?'booked':v.rush_load?'rush_queue':'routine_queue'}};export async function loadParley(){return {cold_chain_booking_score:(a0:number,a1:number,a2:number,a3:boolean)=>BigInt(score(a0,a1,a2,a3))}}
